package com.bank.consistenthash.service;
import java.util.*;
import java.util.logging.*;

public class ConsistentHashRing {
    private static final Logger log = Logger.getLogger(ConsistentHashRing.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final int vnodes;
    private final TreeMap<Long, String> ring = new TreeMap<>();   // ring position -> physical node
    public ConsistentHashRing(int vnodes) { this.vnodes = vnodes; }

    private long hash(String s) { return Math.floorMod((long) s.hashCode() * 2654435761L, 1L << 32); }

    // Each physical node occupies MANY ring positions (virtual nodes)
    public void addNode(String node) {
        for (int i = 0; i < vnodes; i++) ring.put(hash(node + "#" + i), node);
        log.info(() -> "added " + node + " with " + vnodes + " virtual nodes");
    }
    public void removeNode(String node) {
        ring.keySet().removeIf(pos -> ring.get(pos).equals(node));
        log.info(() -> "removed " + node);
    }
    // Key goes to the first node clockwise
    public String route(String key) {
        if (ring.isEmpty()) return null;
        long h = hash(key);
        Map.Entry<Long,String> e = ring.ceilingEntry(h);
        return (e == null ? ring.firstEntry() : e).getValue();
    }
}
