package com.bank.consistenthash;
import com.bank.consistenthash.service.ConsistentHashRing;
import java.util.*;
import java.util.logging.*;

public class HashRingDemo {
    public static void main(String[] args) {
        ConsistentHashRing ring = new ConsistentHashRing(150);
        ring.addNode("shard_0"); ring.addNode("shard_1"); ring.addNode("shard_2");
        List<String> keys = List.of("SAV2001","CUR3001","SAV2002","SAV9001","CUR4001");
        Map<String,String> before = new LinkedHashMap<>();
        keys.forEach(k -> before.put(k, ring.route(k)));
        System.out.println("before: " + before);

        ring.addNode("shard_3");                      // add a node
        int moved = 0;
        for (String k : keys) if (!ring.route(k).equals(before.get(k))) moved++;
        int finalMoved = moved;
        System.out.println("after adding shard_3, keys moved = " + finalMoved + " of " + keys.size());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
